165	/// A single interaction between a guest and the scheduler: first, request resourcees, followed
166	/// by an ACK to "go ahead".  This thread record includes a bit of thread metadata.
167	#[derive(Debug, Clone)]
168	pub struct ThreadNextTurn {
169	    /// The logical Tid of the guest thread.
170	    pub dettid: DetTid,
171	    /// Address of where the child thread Tid will be cleared if CLEARTID was set on clone.
172	    pub child_tid_addr: usize,
173	    /// Request from the thread to the scheduler.
174	    pub req: Ivar<SchedRequest>,
175	    /// A place for the response when that request is fulfilled.
176	    pub resp: Ivar<SchedResponse>,
177	    pub(crate) protocol: parked::TurnProtocol,
178	}
