208	/// Render an already-sorted thread list for a diagnostic, or `none`.
209	fn render_tid_list(tids: &[DetTid]) -> String {
210	    if tids.is_empty() {
211	        "none".to_owned()
212	    } else {
213	        tids.iter()
214	            .map(|t| format!("dtid {}", t))
215	            .collect::<Vec<_>>()
216	            .join(", ")
