220	/// Deterministically pick one element from `choices` using the supplied PRNG,
221	/// returning `None` for an empty slice. This is the single random-selection
222	/// primitive used by the targeted-chaos scheduling points, so their choices stay
223	/// reproducible under a fixed `--fuzz-seed`.
224	fn chaos_pick<T: Copy>(prng: &mut Pcg64Mcg, choices: &[T]) -> Option<T> {
225	    choices.choose(prng).copied()
226	}
