228	fn take_matching_futex_waiters(waiters: &mut Vec<FutexWaiter>, wake_mask: u32) -> Vec<FutexWaiter> {
229	    let (matching, remaining) = std::mem::take(waiters)
230	        .into_iter()
231	        .partition(|waiter| waiter.bitset & wake_mask != 0);
232	    *waiters = remaining;
233	    matching
234	}
