1374	                if empty_queue_skip && !barrier {
1375	                    return Err(SkipTurn);
1376	                }
1377	                let request = state.are_all_quiesced();
1378	                if !barrier && request.is_none() {
1379	                    if !charged {
1380	                        state.bump_global_time(&global_time, last_turn);
1381	                        charged = true;
1382	                    } else if refresh {
1383	                        // A hook can advance real observed logical time. Refresh
1384	                        // eligibility without charging again. An earlier empty
1385	                        // due check leaves the one-event budget available; an
1386	                        // actual pop consumes it until this turn returns.
1387	                        state.bump_global_time(&global_time, &Err(SkipTurn));
1388	                        if !timed_event_processed {
1389	                            timed_event_processed = state.step2b_process_timed();
1390	                        }
1391	                        if let Err(error) = state.select_parked_alarm() {
1392	                            state.fail_parked_selection(error);
1393	                            continue;
1394	                        }
1395	                    }
1396	                    refresh = false;
1397	                    if state.are_all_quiesced().is_some() {
1398	                        continue;
1399	                    }
1400	                    match maintenance {
1401	                        0 => {
1402	                            state.step2_drain_prefix()?;
1403	                            maintenance = 1;
1404	                            continue;
1405	                        }
1406	                        1 => {
1407	                            if !timed_event_processed {
1408	                                timed_event_processed = state.step2b_process_timed();
1409	                            }
1410	                            if let Err(error) = state.select_parked_alarm() {
1411	                                state.fail_parked_selection(error);
1412	                            }
1413	                            maintenance = 2;
1414	                            continue;
1415	                        }
1416	                        2 => {
1417	                            state.step2c_process_io_blockers()?;
1418	                            maintenance = 3;
1419	                            continue;
1420	                        }
1421	                        3 => {
1422	                            state.step2e_process_signal_deferred();
1423	                            maintenance = 4;
1424	                            continue;
1425	                        }
1426	                        4 => {
1427	                            empty_queue_skip =
1428	                                state.step2d_handle_empty_queue(&global_time).is_err();
1429	                            // Select at the time to which the empty queue just
1430	                            // advanced, before a later pass can advance again.
1431	                            if let Err(error) = state.select_parked_alarm() {
1432	                                state.fail_parked_selection(error);
1433	                            }
1434	                            maintenance = 5;
1435	                            continue;
1436	                        }
1437	                        _ => {
1438	                            if let Err(error) = state.select_parked_alarm() {
1439	                                state.fail_parked_selection(error);
1440	                                continue;
1441	                            }
1442	                            // Installing an observation creates an empty callback
1443	                            // gate. Await its hook/finish before any tentative pop.
1444	                            if state.are_all_quiesced().is_some() {
1445	                                continue;
1446	                            }
1447	                            let (tid, req, resp) = state.step3_peek().ok_or(SkipTurn)?;
1448	                            Action::Select(tid, req, resp)
1449	                        }
1450	                    }
1451	                } else {
1452	                    Action::Wait {
1453	                        request,
1454	                        control: state.control_waiter(),
1455	                        barrier,
1456	                    }
1457	                }
1458	            };
1459	            match action {
1460	                Action::Select(tid, req, resp) => {
1461	                    return finish_selected_turn(
1462	                        sched.clone(),
1463	                        global_time.clone(),
1464	                        tid,
1465	                        req,
1466	                        resp,
1467	                    )
1468	                    .await;
1469	                }
1470	                Action::Wait {
1471	                    request,
1472	                    control,
1473	                    barrier,
1474	                } => {
1475	                    if barrier {
1476	                        until_backend_failure(&sched, control).await?;
1477	                    } else if let Some(request) = request {
1478	                        let wait = async {
1479	                            futures::pin_mut!(request, control);
1480	                            let _ = futures::future::select(request, control).await;
1481	                        };
1482	                        until_backend_failure(&sched, wait).await?;
1483	                    }
1484	                    refresh = true;
1485	                }
1486	            }
1487	        }
1488	    }
1489	    .await;
1490	    signal_control::flush_signal_failures(&sched);
1491	    result
1492	}
