2507	    fn choose_futex_wakees(
2508	        &mut self,
2509	        vec: &mut Vec<FutexWaiter>,
2510	        num_woken: usize,
2511	    ) -> Vec<FutexWaiter> {
2512	        if self.fuzz_futexes {
2513	            let rng = &mut self.fuzz_prng;
2514	            debug!(
2515	                "[fuzz-futexes] selecting {} tids, pre shuffle: {:?}",
2516	                num_woken,
2517	                vec.iter().map(|x| x.dettid).collect::<Vec<DetTid>>()
2518	            );
2519	
2520	            // No need to actually use the results here since vec was mutated:
2521	            let (_extracted, _remain) = &vec[..].partial_shuffle(rng, num_woken);
2522	
2523	            info!(
2524	                "[fuzz-futexes] selecting {} tids, post shuffle: {:?}",
2525	                num_woken,
2526	                vec.iter().map(|x| x.dettid).collect::<Vec<DetTid>>()
2527	            );
