2533	    fn take_futex_wakees(
2534	        &mut self,
2535	        futexid: FutexID,
2536	        max_to_wake: i32,
2537	        wake_mask: u32,
2538	    ) -> Vec<FutexWaiter> {
2539	        if max_to_wake == 0 {
2540	            trace!("[detcore] Futex wake of 0 waiters necessarily fizzles...");
2541	            return Vec::new();
2542	        }
2543	        let mut vec: Vec<FutexWaiter> = {
2544	            match self.blocked.futex_waiters.get_mut(&futexid) {
2545	                None => {
2546	                    trace!(
2547	                        "[detcore] Futex wake {} waiters FIZZLED -- none waiting",
2548	                        max_to_wake
2549	                    );
2550	                    return Vec::new();
2551	                }
2552	                Some(r) => std::mem::take(r),
2553	            }
2554	        };
2555	        trace!(
2556	            "Waking up to {} Futex waiters, out of {} waiting.",
2557	            max_to_wake,
2558	            vec.len(),
2559	        );
2560	        let mut matching = take_matching_futex_waiters(&mut vec, wake_mask);
2561	        let num_woken: usize = std::cmp::min(matching.len(), max_to_wake.try_into().unwrap());
2562	        let to_wake = self.choose_futex_wakees(&mut matching, num_woken);
2563	
2564	        assert_eq!(to_wake.len(), num_woken);
2565	        vec.extend(matching);
2566	        // Put back what wasn't woken up:
2567	        if !vec.is_empty() {
2568	            let junk = self.blocked.futex_waiters.insert(futexid, vec);
2569	            assert!(junk.unwrap().is_empty());
2570	        }
2571	        to_wake
2572	    }
