2643	        // return below and before step3 opens a tentative-pop window. Removals
2644	        // drain before admissions so a thread killed while an admission was
2645	        // still buffered is not re-enqueued.
2646	        self.drain_pending_run_queue_removals();
2647	        self.drain_pending_cross_task_signals();
