2680	    /// Re-admit parents whose host-async `SIGCHLD` was parked in
2681	    /// `blocked.sigchld_deferred` (see `block_for_one_resource`). Uses the same
2682	    /// deterministic-work-first gate as `step2c_process_io_blockers`: a deferred
2683	    /// signal is delivered only once the run queue holds no ordinary (non-poller)
2684	    /// guest work, so its commit order is fixed by the scheduler rather than by
2685	    /// host signal-arrival timing. Runs after external-IO harvesting so a ready
2686	    /// IO continuation is always ordered ahead of a deferred signal.
2687	    fn step2e_process_signal_deferred(&mut self) {
2688	        if self.blocked.sigchld_deferred.is_empty() {
2689	            return;
2690	        }
2691	        let only_pollers = match self.run_queue.first_priority() {
2692	            Some(fp) => fp >= LAST_PRIORITY,
2693	            None => true,
2694	        };
2695	        if !self.run_queue.is_empty() && !only_pollers {
2696	            return;
2697	        }
2698	        // BTreeSet drains in sorted DetTid order, giving a canonical admission
2699	        // order when several parents are owed a signal at the same quiescence.
2700	        let ready = std::mem::take(&mut self.blocked.sigchld_deferred);
2701	        for dtid in ready {
2702	            info!("[step2] Re-admit deferred SIGCHLD for dtid {:?}", dtid);
2703	            self.blocked.sigchld_ready.insert(dtid);
2704	            self.run_queue.push_eager_io_repoll(dtid);
2705	        }
2706	    }
