3164	    /// Classify a request that still represents the same in-flight waitid.
3165	    /// A signal may arrive before its polling request is rewritten or after a prior
3166	    /// notification has already materialized its scheduler wakeup.
3167	    fn waitid_signal_request(&self, dettid: DetTid) -> Option<WaitidSignalRequest> {
3168	        let resources = self
3169	            .next_turns
3170	            .get(&dettid)
3171	            .and_then(|next_turn| next_turn.req.try_read())
3172	            .and_then(Result::ok)?;
3173	        // The two ways to be parked inside wait4/waitid: the legacy kernel
3174	        // polling loop, and the scheduler-managed child-wait lifecycle resource
3175	        // added by the typed WaitChild work. Both must be woken; neither implies
3176	        // anything about run-queue residency, which the drain decides.
3177	        let waiting_on_child = resources
3178	            .resources
3179	            .keys()
3180	            .any(|resource| matches!(resource, ResourceID::WaitChild { .. }));
3181	        let legacy_polling = resources.fyi == "waitid"
3182	            && resources
3183	                .resources
3184	                .contains_key(&ResourceID::InternalIOPolling);
3185	        if legacy_polling || waiting_on_child {
3186	            return Some(WaitidSignalRequest::Parked);
3187	        }
3188	        // Signals already materialized on this waitid request by an earlier
3189	        // drain. A marked `WaitidSignals` resource instead belongs to an
3190	        // interrupted InternalIOPolling request and is classified below.
3191	        if resources.signal_interrupt_errno().is_some() {
3192	            return None;
3193	        }
3194	        resources
3195	            .resources
3196	            .keys()
3197	            .find_map(|resource| match resource {
3198	                ResourceID::WaitidSignals(signals) => {
3199	                    Some(WaitidSignalRequest::Pending(signals.clone()))
3200	                }
3201	                _ => None,
3202	            })
3203	    }
