3210	            .get(&dettid)
3211	            .and_then(|next_turn| next_turn.req.try_read())
3212	            .and_then(Result::ok)
3213	            .and_then(|resources| {
3214	                if resources.resources.len() != 1
3215	                    || resources.signal_interrupt_errno() != Some(Errno::ERESTARTSYS.into_raw())
3216	                {
3217	                    return None;
3218	                }
3219	                match resources.resources.keys().next() {
3220	                    Some(ResourceID::InternalIOPolling) => Some(Vec::new()),
