3517	    /// Build the deadlock report. **Must be byte-identical across runs of the
3518	    /// same program**: this text reaches stderr, and emitting a
3519	    /// host-dependent string from a deterministic execution engine is a defect
3520	    /// in its own right, whether or not any comparator currently catches it.
3521	    ///
3522	    /// The obvious implementation -- `{:?}` of `run_queue`, `next_turns` and
3523	    /// `blocked` -- is *not* reproducible. Three independent sources of
3524	    /// run-to-run variation hide in those structures:
3525	    ///
3526	    /// 1. `ThreadNextTurn` and `FutexWaiter` hold [`Ivar`]s whose `Debug` prints
3527	    ///    the parked waker as `Waker { data: 0x55.., vtable: 0x55.. }` -- raw
3528	    ///    host pointers that move with ASLR on every run.
3529	    /// 2. `BlockedPool::futex_waiters` is a `HashMap` and
3530	    ///    `timed_out_futex_waiters` a `HashSet`, so both iterate in a
3531	    ///    randomized order whenever they hold more than one entry.
3532	    /// 3. `Resources::resources` is itself a `HashMap`, so even a single
3533	    ///    thread's resource list is unordered.
3534	    ///
3535	    /// So every collection below is sorted on a stable key, and only
3536	    /// guest-level identities are printed: dettids, resource ids, futex keys and
3537	    /// logical deadlines, all of which Detcore already guarantees to be
3538	    /// deterministic. No host pointer is emitted.
3539	    fn format_terminal_deadlock(&self) -> String {
3540	        // ⚠️ ADDING A SECTION HERE? RENDER `dtid` OR A STABLE ORDINAL, NEVER A
3541	        // DEBUG-FORMATTED ID. The rule is stated in full in the doc comment above
3542	        // and repeated here because that is not where authors edit: the doc
3543	        // comment already warned that the obvious `{:?}` implementation is not
3544	        // reproducible, and a later change added a section that did it anyway.
3545	        //
3546	        // A host-influenced counter is the failure that survives review, because
3547	        // it LOOKS like a small integer. `{:?}` of a wrapper type, a raw thread
3548	        // id, an allocation counter or anything seeded from host state will differ
3549	        // run to run while reading like an ordinary index.
3550	        //
3551	        // Print only identities Detcore already determinizes: dettids, resource
3552	        // ids, futex keys, logical deadlines, or a position computed by sorting on
3553	        // one of those.
3554	        //
3555	        // ⚠️ AND EXTEND THE FIXTURE. The determinism test cannot see a section its
3556	        // fixture never renders, so a section that only appears under state
3557	        // `deadlocked_scheduler` does not build is UNGUARDED however good the
3558	        // banned list is. If your section needs different scheduler state, add
3559	        // that state to the fixture in the same change.
3560	        let mut out = format!(
3561	            "Deadlock detected: {}, but no runnable threads left.\n",
3562	            self.describe_terminal_waiters()
3563	        );
3564	        let _ = writeln!(
3565	            out,
3566	            "  turn {}, committed time {}",
3567	            self.turn, self.committed_time
3568	        );
3569	        let _ = writeln!(out, "  run queue: {} runnable", self.run_queue.len());
3570	
3571	        let _ = writeln!(out, "  threads ({}), by dettid:", self.next_turns.len());
3572	        // `next_turns` is a BTreeMap, so this walk is already ordered.
