        && self.blocked.child_waiters.is_empty()
        && self.blocked.physical_child_waiters.is_empty();
    let rt_sigsuspend_empty = self.blocked.rt_sigsuspend_blockers.is_empty();
    let futex_empty = self.blocked.no_futex_waiters();

