3913	    /// Deschedule, but do not clear request/response. This should be used when
3914	    /// the turn was skipped because the blocked-on resource is still blocking.
3915	    fn skip_turn_blocked(&mut self, dettid: DetTid) -> Result<(), SkipTurn> {
3916	        self.run_queue.undo_tentative_pop(); // Started in step3.
3917	        assert!(self.run_queue.remove_tid(dettid)); // Deschedule while we wait.
3918	        trace!(
3919	            "[dtid {}] after removal, run queue: {:?}",
3920	            dettid, &self.run_queue
3921	        );
3922	        self.skip_turn()
3923	    }
