4349	    fn step1_check_quiescence(
4350	        &mut self,
4351	        global_time: &Mutex<GlobalTime>,
4352	        last_turn: &Result<Resources, SkipTurn>,
4353	    ) -> Option<Ivar<SchedRequest>> {
4354	        // TODO: actually check resource availability to enable asynchronous background activities!
4355	        let outstanding = self.are_all_quiesced();
4356	        if outstanding.is_none() {
4357	            self.bump_global_time(global_time, last_turn);
4358	        }
