5278	        )
5279	        .unwrap();
5280	        // Sorted, and no `Ivar` Debug. `format_terminal_deadlock` above already
5281	        // documents the two sources this avoids, and this function had neither
5282	        // guard: `futex_waiters` is a `HashMap`, so it iterates in a randomized
5283	        // order once it holds more than one entry, and `FutexWaiter`'s derived
5284	        // `Debug` prints its `Ivar`'s parked waker as raw host pointers.
5285	        //
5286	        // Measured before this change, three runs of
5287	        // `--stop-after-turn=15 -- rustbin_futex_and_print`, which reaches this
5288	        // function through the `--stop-after-turn` warning:
5289	        //   Waker { data: 0x564ea2a82c80
5290	        //   Waker { data: 0x55f2120b9c80
5291	        //   Waker { data: 0x56163deeec80
5292	        // Three runs, three host addresses, in a WARN record that
5293	        // `--verify-strict` compares.
5294	        //
5295	        // Only guest-level identities are printed here: the futex key, the
5296	        // waiting dettid and the bitset are all values Detcore already
5297	        // determinizes.
5298	        let mut futex_rows: Vec<String> = self
5299	            .blocked
5300	            .futex_waiters
5301	            .iter()
5302	            .map(|(futex, waiters)| {
5303	                let mut dettids: Vec<String> =
