5336	        )
5337	        .unwrap();
5338	        for x in &self.blocked.external_io_blockers {
5339	            writeln!(&mut buf, "    {:?}", x).unwrap();
5340	        }
5341	
5342	        writeln!(
5343	            &mut buf,
