5988	        // entry is gone. Iterating quiescence must SKIP the victim (filtered by
5989	        // pending_run_queue_removals) rather than panic in check_request on the
5990	        // missing next_turns entry -- without the filter this call panics.
5991	        sched.next_turns.remove(&victim);
5992	        let _ = sched.are_all_quiesced();
