6024	        assert!(sched.run_queue.contains_tid(victim), "removal deferred");
6025	
6026	        // The daemon applies them at the drain (removals first, then admissions).
6027	        sched.drain_pending_run_queue_removals();
6028	        sched.drain_pending_run_queue_admissions();
6029	        assert!(sched.run_queue.contains_tid(keep));
6030	        assert!(!sched.run_queue.contains_tid(victim));
