6217	    #[derive(Debug, PartialEq, Eq)]
6218	    struct ExecDrainObservation {
6219	        queue: Vec<DetTid>,
6220	        next_post_fork_draw: bool,
6221	        turn: u64,
6222	        old_leader_registration_survived: bool,
6223	    }
