7150	        let target = DetTid::from_raw(100);
7151	        register_known_thread(&mut scheduler, target);
7152	        // The shape that crashed: an ordinary delivered signal, nothing to do
7153	        // with waitid.
7154	        let mut inbound = Resources::new(target);
7155	        inbound.insert(
7156	            ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR1)),
7157	            Permission::W,
7158	        );
7159	        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(inbound));
7160	        scheduler.runqueue_push_back(target);
