7179	    /// A thread can hold a `WaitChild` request while ALREADY in the run queue:
7180	    /// `wake_child_waiters` re-admits a waiter without clearing its request, and
7181	    /// `step6_reenqueue` pushes a completed turn back before the guest issues
7182	    /// its next request. An earlier revision inferred "blocked" from the
7183	    /// resource and skipped the run-queue removal, so the drain pushed a
7184	    /// second copy of the thread.
7185	    ///
7186	    /// That failure is worse than it looks: `RunQueue`'s duplicate check is
7187	    /// `cfg!(debug_assertions)`, so debug builds panic with "Invariant
7188	    /// violation! Tried to add ... already present" while RELEASE builds
7189	    /// silently enqueue the thread twice and select it twice.
7190	    #[test]
7191	    fn pending_signal_does_not_double_queue_a_runnable_child_waiter() {
7192	        let mut scheduler = Scheduler::new(&Config::default());
7193	        let target = DetTid::from_raw(100);
7194	        let parent = DetPid::from_raw(100);
7195	        register_known_thread(&mut scheduler, target);
7196	        let spec = ChildWaitSpec {
7197	            selector: ChildWaitSelector::Any,
7198	            owner: None,
7199	            exit_class: ChildWaitExitClass::Sigchld,
7200	        };
7201	        let mut waiting = Resources::new(target);
7202	        waiting.insert(ResourceID::WaitChild { parent, spec }, Permission::R);
7203	        waiting.fyi("wait-child-lifecycle");
7204	        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(waiting));
7205	        // The distinguishing state: holds WaitChild AND is runnable, with no
7206	        // `child_waiters` entry -- exactly what a just-woken waiter looks like.
7207	        scheduler.runqueue_push_back(target);
7208	        assert!(scheduler.run_queue.contains_tid(target));
7209	        assert!(!scheduler.blocked.child_waiters.contains_key(&target));
7210	
7211	        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
7212	        scheduler.drain_pending_cross_task_signals();
7213	
7214	        let occurrences = scheduler
7215	            .run_queue
7216	            .tids()
7217	            .filter(|tid| **tid == target)
7218	            .count();
7219	        assert_eq!(
7220	            occurrences, 1,
7221	            "the signalled child waiter must appear in the run queue exactly once"
7222	        );
