7842	    /// The deadlock report reaches stderr, so it must be byte-identical across
7843	    /// runs of the same program. Codex measured the unguarded `{:?}` dump
7844	    /// emitting `Waker { data: 0x557e90a74680, .. }` in one run and
7845	    /// `Waker { data: 0x5654e2b08680, .. }` in the next: raw host pointers that
7846	    /// move with ASLR. Assert the render carries no host pointer and no
7847	    /// insertion-order dependence.
7848	    #[test]
7849	    fn deadlock_report_is_deterministic_and_carries_no_host_pointer() {
7850	        let config = Config::default();
7851	        let forward = deadlocked_scheduler(&config, false).format_terminal_deadlock();
7852	        let reversed = deadlocked_scheduler(&config, true).format_terminal_deadlock();
7853	
7854	        // Same logical state built in two insertion orders must render
7855	        // identically: no HashMap/HashSet iteration order may leak.
7856	        assert_eq!(forward, reversed);
7857	
7858	        // No `Debug` of an Ivar/Waker, and so no host pointer.
7859	        //
7860	        // ⚠️ THIS LIST CANNOT SEE A SECTION THE FIXTURE NEVER RENDERS. It only
7861	        // inspects the text `deadlocked_scheduler` happens to produce. When you
7862	        // add a section to `format_terminal_deadlock`, add the state that triggers
7863	        // it to the fixture in the same change, or this test will pass and say
7864	        // nothing about your section.
7865	        //
7866	        // These tokens catch host POINTERS and raw thread ids. The subtler failure
7867	        // is a host-influenced COUNTER, which looks like an ordinary small integer
7868	        // and matches no banned word -- which is why the byte-identical assertion
7869	        // above is the load-bearing check and this list is only a backstop.
7870	        for banned in [
7871	            "Waker", "Ivar", "vtable", "Mutex", "poisoned", "ThreadId", "0x7f",
7872	        ] {
7873	            assert!(
7874	                !forward.contains(banned),
7875	                "deadlock report leaked {banned:?}; it must print only guest-level \
7876	                 identities.\n{forward}"
7877	            );
7878	        }
7879	
7880	        // The report is still substantive: it names every blocked thread, the
7881	        // futex keys, and the indefinite deadline.
7882	        for expected in [
7883	            // This fixture holds BOTH pools, so the state-derived headline must
7884	            // name both rather than whichever branch happened to fire.
7885	            "Deadlock detected: thread(s) waiting on futex, and thread(s) waiting \
7886	             indefinitely (pause, or a timer beyond the end of logical time), but no \
7887	             runnable threads left.",
7888	            "dtid 3",
7889	            "dtid 9",
7890	            "0x404100",
7891	            "0x404300",
7892	            "INDEFINITE (no deadline)",
7893	            "FutexWait: R, MemAddrSpace(DetPid(3)): RW",
7894	        ] {
7895	            assert!(
7896	                forward.contains(expected),
7897	                "deadlock report lost {expected:?}:\n{forward}"
7898	            );
7899	        }
7900	    }
