7	
8	//! Run-scoped callback-independent process publication and recipient permits.
9	//!
10	//! Installation precedes guest startup. A permit authorizes one actual task
11	//! continuation, not a host wake or an unrelated borrowed Guest. Generation-
12	//! bound child completion is published through this same run-scoped control.
13	//!
14	//! Active publication uses only transaction -> lifecycle -> run failure ->
15	//! process signals and pinned private eventfd carriers. It never acquires or
16	//! pins the ordinary file table. The retained inactive alarm test endpoint
17	//! additionally takes file table first, preserving its negative controls.
18	//! Image validation briefly reacquires image below transaction;
19	//! child lookup briefly reacquires registry below lifecycle. Those guards are
20	//! released before failure/process acquisition. The run failure guard remains
21	//! held through readiness I/O after process/lifecycle guards are released,
22	//! serializing publications across
23	//! processes in this run. Existing executor process/thread locks remain below
24	//! the transaction. No registry or retirement mutex is held during host closes.
25	
26	use std::collections::BTreeMap;
27	use std::sync::Arc;
28	use std::sync::Mutex;
29	use std::sync::Weak;
30	use std::sync::atomic::AtomicBool;
31	use std::sync::atomic::Ordering;
32	
33	use reverie::SignalEvent;
34	use reverie::SignalProcessId;
35	use reverie::syscalls::Errno;
36	
37	use super::FileTableState;
38	use super::LoadedStaticElf;
39	use super::set_signalfd_ready;
40	use crate::elf::TaskLifecycleTable;
41	use crate::signal::ProcessSignalState;
42	
43	#[derive(Clone, Debug)]
44	struct ImageRevision(Arc<()>);
45	
46	impl PartialEq for ImageRevision {
47	    fn eq(&self, other: &Self) -> bool {
48	        Arc::ptr_eq(&self.0, &other.0)
49	    }
50	}
51	
52	impl Eq for ImageRevision {}
53	
54	#[derive(Clone)]
55	struct CurrentImage {
56	    revision: ImageRevision,
57	    files: Weak<Mutex<FileTableState>>,
58	    signals: Weak<Mutex<ProcessSignalState>>,
59	}
60	
61	/// Executors own this binding; the run registry never owns a process or image.
62	/// Threads share it, fork registers a fresh binding, and exec replaces `image`.
63	pub(super) struct ProcessBinding {
64	    identity: SignalProcessId,
65	    parent: Option<SignalProcessId>,
66	    transaction: Weak<Mutex<()>>,
67	    lifecycle: Weak<Mutex<TaskLifecycleTable>>,
68	    image: Mutex<CurrentImage>,
69	}
70	
71	impl ProcessBinding {
72	    pub(super) fn rebind(&self, state: &LoadedStaticElf, files: &Arc<Mutex<FileTableState>>) {
73	        // Caller holds the authoritative file table and process transaction.
74	        *self.image.lock().unwrap_or_else(|p| p.into_inner()) = CurrentImage {
75	            revision: ImageRevision(Arc::new(())),
76	            files: Arc::downgrade(files),
77	            signals: Arc::downgrade(&state.process_signals),
78	        };
79	    }
80	}
81	
82	#[derive(Default)]
83	pub(super) struct ProcessSignalRegistry {
84	    processes: Mutex<BTreeMap<(i32, u64), Weak<ProcessBinding>>>,
85	    // No callbacks or G references. An eventual owner must make its own run
86	    // terminal after saving FailedAfterCommit. This latch refuses further
87	    // publication; it is not a substitute for that owner transition.
88	    failure: Mutex<Option<PublicationFailure>>,
89	    controlled: AtomicBool,
90	    permits: Mutex<BTreeMap<(i32, u64, i32, u64), RegisteredPermit>>,
91	    completed_permits: Mutex<BTreeMap<(i32, u64, i32, u64), reverie::SignalDeliveryPermit>>,
92	    run_failure: Mutex<Weak<crate::failure::RunFailure>>,
93	    reported_failure: Mutex<Option<crate::Error>>,
94	}
95	
96	impl ProcessSignalRegistry {
97	    pub(super) fn register(
98	        &self,
99	        state: &LoadedStaticElf,
100	        files: &Arc<Mutex<FileTableState>>,
101	        generation: u64,
102	        parent: Option<SignalProcessId>,
103	    ) -> Arc<ProcessBinding> {
104	        let binding = Arc::new(ProcessBinding {
105	            identity: SignalProcessId {
106	                tgid: reverie::Pid::from_raw(state.pid),
107	                generation,
108	            },
109	            parent,
110	            transaction: Arc::downgrade(&state.signal_transaction),
111	            lifecycle: Arc::downgrade(&state.task_lifecycle),
112	            image: Mutex::new(CurrentImage {
113	                revision: ImageRevision(Arc::new(())),
114	                files: Arc::downgrade(files),
115	                signals: Arc::downgrade(&state.process_signals),
116	            }),
117	        });
118	        let mut processes = self.processes.lock().unwrap_or_else(|p| p.into_inner());
119	        processes.retain(|_, process| process.strong_count() != 0);
120	        processes.insert((state.pid, generation), Arc::downgrade(&binding));
121	        binding
122	    }
123	
124	    fn lookup(&self, identity: SignalProcessId) -> Option<Arc<ProcessBinding>> {
125	        self.processes
126	            .lock()
127	            .unwrap_or_else(|p| p.into_inner())
128	            .get(&(identity.tgid.as_raw(), identity.generation))?
129	            .upgrade()
130	    }
131	
132	    pub(super) fn control(self: &Arc<Self>) -> ProcessSignalControl {
133	        ProcessSignalControl(Arc::downgrade(self))
134	    }
135	}
136	
137	/// Retaining a control does not retain executors, descriptors, or GlobalState.
138	pub(super) struct ProcessSignalControl(Weak<ProcessSignalRegistry>);
139	
140	impl std::fmt::Debug for ProcessSignalControl {
141	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
142	        f.debug_struct("ProcessSignalControl")
143	            .finish_non_exhaustive()
144	    }
145	}
146	
147	#[derive(Clone)]
148	struct RegisteredPermit {
149	    permit: reverie::SignalDeliveryPermit,
150	    image: ImageRevision,
151	}
152	
153	fn task_key(task: reverie::SignalTaskIdentity) -> (i32, u64, i32, u64) {
154	    (
155	        task.process.tgid.as_raw(),
156	        task.process.generation,
157	        task.tid.as_raw(),
158	        task.task_generation,
159	    )
160	}
161	
162	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
163	pub(super) enum PublicationRejection {
164	    Closed,
165	    StaleProcess,
166	    ChangedImage,
167	    InvalidEvent,
168	    InvalidCompletion,
169	    Backend(Errno),
170	    Terminal,
171	}
172	
173	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
174	pub(super) enum PublicationDisposition {
175	    Ignored,
176	    Default,
177	    Caught,
178	}
179	
180	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
181	pub(super) enum PendingChange {
182	    Queued,
183	    Coalesced,
184	    Suppressed,
185	}
186	
187	#[derive(Clone, Debug, Eq, PartialEq)]
188	pub(super) struct PublicationReceipt {
189	    process: SignalProcessId,
190	    image: ImageRevision,
191	    signal: i32,
192	    pending_generation: u64,
193	    change: PendingChange,
194	    disposition: PublicationDisposition,
195	    child_completion: Option<reverie::ChildExitCompletion>,
196	}
197	
198	#[derive(Clone, Debug, Eq, PartialEq)]
199	pub(super) struct PublicationFailure {
200	    receipt: PublicationReceipt,
201	    errno: Errno,
202	}
203	
204	#[derive(Clone, Debug, Eq, PartialEq)]
205	pub(super) enum ProcessPublication {
206	    Rejected(PublicationRejection),
207	    Committed(PublicationReceipt),
208	    FailedAfterCommit(PublicationFailure),
209	}
210	
211	impl ProcessSignalControl {
212	    #[cfg_attr(
213	        not(test),
214	        expect(
215	            dead_code,
216	            reason = "retained inactive private endpoint; active facade uses independent carriers"
217	        )
218	    )]
219	    pub(super) fn publish_alarm(
220	        &self,
221	        target: SignalProcessId,
222	        event: SignalEvent,
223	    ) -> ProcessPublication {
224	        let mut expected = [0; reverie::SIGNAL_INFO_SIZE];
225	        expected[..4].copy_from_slice(&libc::SIGALRM.to_ne_bytes());
226	        expected[8..12].copy_from_slice(&libc::SI_KERNEL.to_ne_bytes());
227	        if event.signal() != libc::SIGALRM
228	            || event.siginfo() != expected
229	            || event.target() != (reverie::SignalTarget::Process { pid: target.tgid })
230	        {
231	            return ProcessPublication::Rejected(PublicationRejection::InvalidEvent);
232	        }
233	        self.publish(target, event, None, false)
234	    }
235	
236	    fn publish_active_alarm(
237	        &self,
238	        target: SignalProcessId,
239	        event: SignalEvent,
240	    ) -> ProcessPublication {
241	        let mut expected = [0; reverie::SIGNAL_INFO_SIZE];
242	        expected[..4].copy_from_slice(&libc::SIGALRM.to_ne_bytes());
243	        expected[8..12].copy_from_slice(&libc::SI_KERNEL.to_ne_bytes());
244	        if event.signal() != libc::SIGALRM
245	            || event.siginfo() != expected
246	            || event.target() != (reverie::SignalTarget::Process { pid: target.tgid })
247	        {
248	            return ProcessPublication::Rejected(PublicationRejection::InvalidEvent);
249	        }
250	        self.publish(target, event, None, true)
251	    }
252	
253	    fn publish_child_completion(
254	        &self,
255	        completion: reverie::ChildExitCompletion,
256	    ) -> ProcessPublication {
257	        if completion.user_ticks < 0 || completion.system_ticks < 0 {
258	            return ProcessPublication::Rejected(PublicationRejection::InvalidCompletion);
259	        }
260	        let (code, status) = match completion.status {
261	            reverie::ExitStatus::Exited(status) if (0..=i32::from(u8::MAX)).contains(&status) => {
262	                (libc::CLD_EXITED, status)
263	            }
264	            reverie::ExitStatus::Exited(_) => {
265	                return ProcessPublication::Rejected(PublicationRejection::InvalidCompletion);
266	            }
267	            reverie::ExitStatus::Signaled(signal, true) => {
268	                (libc::CLD_DUMPED, signal as libc::c_int)
269	            }
270	            reverie::ExitStatus::Signaled(signal, false) => {
271	                (libc::CLD_KILLED, signal as libc::c_int)
272	            }
273	        };
274	        let mut info = [0; reverie::SIGNAL_INFO_SIZE];
275	        info[..4].copy_from_slice(&libc::SIGCHLD.to_ne_bytes());
276	        info[8..12].copy_from_slice(&code.to_ne_bytes());
277	        info[16..20].copy_from_slice(&completion.child.tgid.as_raw().to_ne_bytes());
278	        info[20..24].copy_from_slice(&completion.uid.to_ne_bytes());
279	        info[24..28].copy_from_slice(&status.to_ne_bytes());
280	        info[32..40].copy_from_slice(&completion.user_ticks.to_ne_bytes());
281	        info[40..48].copy_from_slice(&completion.system_ticks.to_ne_bytes());
282	        let event = SignalEvent::new(
283	            libc::SIGCHLD,
284	            info,
285	            reverie::SignalTarget::Process {
286	                pid: completion.parent.tgid,
287	            },
288	        );
289	        let Ok(event) = event else {
290	            return ProcessPublication::Rejected(PublicationRejection::InvalidCompletion);
291	        };
292	        self.publish(completion.parent, event, Some(&completion), true)
293	    }
294	
295	    fn publish(
296	        &self,
297	        target: SignalProcessId,
298	        event: SignalEvent,
299	        completion: Option<&reverie::ChildExitCompletion>,
300	        independent_carriers: bool,
301	    ) -> ProcessPublication {
302	        use ProcessPublication::Rejected;
303	        use PublicationRejection::*;
304	        let Some(registry) = self.0.upgrade() else {
305	            return Rejected(Closed);
306	        };
307	        let Some(binding) = registry.lookup(target) else {
308	            return Rejected(StaleProcess);
309	        };
310	        let image = binding
311	            .image
312	            .lock()
313	            .unwrap_or_else(|p| p.into_inner())
314	            .clone();
315	        let (Some(transaction), Some(lifecycle), Some(signals)) = (
316	            binding.transaction.upgrade(),
317	            binding.lifecycle.upgrade(),
318	            image.signals.upgrade(),
319	        ) else {
320	            return Rejected(StaleProcess);
321	        };
322	        // The active path neither acquires nor pins an ordinary file table:
323	        // even dropping its final Arc could close an unrelated blocking socket
324	        // while the Tool holds its scheduler mutex. Only the inactive private
325	        // endpoint retains its historical table preflight and corruption checks.
326	        let files_owner = if independent_carriers {
327	            None
328	        } else {
329	            let Some(files) = image.files.upgrade() else {
330	                return Rejected(StaleProcess);
331	            };
332	            Some(files)
333	        };
334	        let files = match files_owner.as_ref() {
335	            Some(files) => match files.lock() {
336	                Ok(files) => Some(files),
337	                Err(_) => return Rejected(Backend(Errno::EIO)),
338	            },
339	            None => None,
340	        };
341	        let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
342	        if binding
343	            .image
344	            .lock()
345	            .unwrap_or_else(|p| p.into_inner())
346	            .revision
347	            != image.revision
348	        {
349	            return Rejected(ChangedImage);
350	        }
351	        let lifecycle = lifecycle.lock().unwrap_or_else(|p| p.into_inner());
352	        if binding.identity != target
353	            || !lifecycle.contains_process(target.tgid.as_raw(), target.generation)
354	        {
355	            return Rejected(StaleProcess);
356	        }
357	        if let Some(completion) = completion {
358	            let Some(child) = registry.lookup(completion.child) else {
359	                return Rejected(InvalidCompletion);
360	            };
361	            if child.parent != Some(target)
362	                || lifecycle.process_exit_status(
363	                    completion.child.tgid.as_raw(),
364	                    completion.child.generation,
365	                ) != Some(completion.status)
366	            {
367	                return Rejected(InvalidCompletion);
368	            }
369	        }
370	        // Serialize the run-local terminal latch through the entire commit.
371	        // This also prevents a different process from publishing after the
372	        // first failed readiness transaction. No Tool call can occur here.
373	        let mut failure = registry.failure.lock().unwrap_or_else(|p| p.into_inner());
374	        if failure.is_some() {
375	            return Rejected(Terminal);
376	        }
377	        let mut process = signals.lock().unwrap_or_else(|p| p.into_inner());
378	        let signal = event.signal();
379	        let action = process
380	            .dispositions
381	            .get(&signal)
382	            .copied()
383	            .unwrap_or_default();
384	        let disposition = if action.is_ignored() {
385	            PublicationDisposition::Ignored
386	        } else if action.handler == libc::SIG_DFL as u64 {
387	            PublicationDisposition::Default
388	        } else {
389	            PublicationDisposition::Caught
390	        };
391	        if let Some(completion) = completion {
392	            let auto_reap = action.is_ignored() || action.flags & libc::SA_NOCLDWAIT as u64 != 0;
393	            if completion.waitable == auto_reap {
394	                return Rejected(InvalidCompletion);
395	            }
396	        }
397	        let mut receipt = PublicationReceipt {
398	            process: target,
399	            image: image.revision,
400	            signal,
401	            pending_generation: process.pending_generation(signal),
402	            change: PendingChange::Suppressed,
403	            disposition,
404	            child_completion: completion.copied(),
405	        };
406	        if signal == libc::SIGCHLD && action.is_ignored() {
407	            return ProcessPublication::Committed(receipt);
408	        }
409	        let matching = process
410	            .signalfd_masks
411	            .iter()
412	            .filter_map(|(&fd, mask)| mask.contains(signal).then_some(fd))
413	            .collect::<Vec<_>>();
414	        let carriers = if independent_carriers {
415	            let Some(carriers) = matching
416	                .iter()
417	                .map(|fd| process.signalfd_carriers.get(fd).cloned())
418	                .collect::<Option<Vec<_>>>()
419	            else {
420	                return Rejected(Backend(Errno::EBADF));
421	            };
422	            carriers
423	        } else {
424	            if matching.iter().any(|fd| {
425	                !files
426	                    .as_ref()
427	                    .expect("private endpoint owns table")
428	                    .files
429	                    .contains_key(fd)
430	            }) {
431	                return Rejected(Backend(Errno::EBADF));
432	            }
433	            Vec::new()
434	        };
435	        receipt.change = match process
436	            .shared_pending
437	            .enqueue(event, receipt.pending_generation)
438	        {
439	            Ok(true) => PendingChange::Queued,
440	            Ok(false) => PendingChange::Coalesced,
441	            Err(errno) => return Rejected(Backend(errno)),
442	        };
443	        // Release queue/lifecycle locks, retaining descriptor+transaction
444	        // ownership across only bounded, nonblocking eventfd readiness I/O.
445	        drop(process);
446	        drop(lifecycle);
447	        for (index, fd) in matching.into_iter().enumerate() {
448	            let file = if independent_carriers {
449	                carriers[index].file()
450	            } else {
451	                &files.as_ref().expect("private endpoint owns table").files[&fd]
452	            };
453	            if let Err(raw) = set_signalfd_ready(file, true) {
454	                let committed = PublicationFailure {
455	                    receipt,
456	                    errno: Errno::new(i32::try_from(-raw).unwrap_or(libc::EIO)),
457	                };
458	                *failure = Some(committed.clone());
459	                return ProcessPublication::FailedAfterCommit(committed);
460	            }
461	        }
462	        ProcessPublication::Committed(receipt)
463	    }
464	}
