562	fn report_publication_failure(
563	    registry: &ProcessSignalRegistry,
564	    process: SignalProcessId,
565	    phase: &'static str,
566	    error: crate::Error,
567	) -> Result<(), Errno> {
568	    let run = registry
569	        .run_failure
570	        .lock()
571	        .unwrap_or_else(|p| p.into_inner())
572	        .upgrade()
573	        .ok_or(Errno::ESRCH)?;
574	    // No scheduler, registry, image or signal lock survives this call.
575	    let context = crate::failure::FailureContext::new(run, process.tgid, process.tgid);
576	    let published = context.publish(phase, error);
577	    // The first run cause may be a concurrent independent failure. Keep this
578	    // returned Error too, so root completion retains the committed publication
579	    // receipt as secondary cleanup rather than losing it.
580	    registry
581	        .reported_failure
582	        .lock()
583	        .unwrap_or_else(|p| p.into_inner())
584	        .get_or_insert(published);
585	    Ok(())
586	}
