588	impl reverie::ProcessSignalControl for ProcessSignalControl {
589	    fn publish_alarm(
590	        &self,
591	        process: SignalProcessId,
592	        event: SignalEvent,
593	    ) -> reverie::ProcessSignalPublicationResult {
594	        use reverie::ProcessSignalPublicationResult as Outcome;
595	        match self.publish_active_alarm(process, event) {
