/// Commit a guest task's exit while retiring its exact identity. Host
/// handle completion and failed child preparation do not select a status.
pub(crate) fn exit(
    &mut self,
    tid: i32,
    generation: u64,
    status: ExitStatus,
    group: bool,
) -> ExitStatus {
    let Some(task) = self.tasks.get(&tid).copied() else {
        return status;
