    if task.generation != generation {
        return status;
    }
    let exit = self
        .process_exits
        .entry((task.tgid, task.process_generation))
        .or_default();
    if group {
        exit.group.get_or_insert(status);
    }
    exit.last_thread = Some(status);
    let status = exit.group.unwrap_or(status);
