1213	    fn active_publication_failure_retains_receipt_beside_prior_run_cause() {
1214	        let mut executor = executor();
1215	        let process = identity(&executor);
1216	        let global = Arc::new(());
1217	        let run = crate::failure::RunFailure::new(&global);
1218	        executor
1219	            .signal_registry
1220	            .install(reverie::BackendSignalControlMode::ToolControlled, &run);
1221	        let context = crate::failure::FailureContext::new(run.clone(), process.tgid, process.tgid);
